G=load()
# Compare top block vs bottom block per demo to find the shift that maps one onto the other EXACTLY (with wraparound columns).
for n in [1,2,3,4]:
    T=G[f'Demo pair {n} input']
    th=len(T); w=len(T[0])
    vals=Counter(v for r in T for v in r).most_common(1)[0][0]
    truns=[]; i=0
    while i<th:
        if any(T[i][j]!=vals for j in range(w)):
            s=i
            while i<th and any(T[i][j]!=vals for j in range(w)): i+=1
            truns.append((s,i-1))
    best=None
    for dy,dx in itertools.product(range(th),range(w)):
        mm=0
        for s,e in truns:
            for i in range(s,e+1):
                for j in range(w):
                    v=T[s+i-dy][j-dx] if 0<=s+i-dy<e+1 else -1
                    # simpler: compare shifted grid values where within bounds
                    ti=i-dy
                    tj=j-dx
                    if ti>=th or tj<0 or tj>=w: continue
                    if T[i][j]!=T[ti][tj]: mm+=1
        if best is None or mm<best[0]: best=(mm,dy,dx)
    print(n,'best mismatch map',best)

