def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))
for i in [1,2,3,4]:
    a=G[f'Demo pair {i} input']; b=G[f'Demo pair {i} output']
    H=len(a); W=len(a[0])
    cnt=Counter(v for r_ in a for v in r_)
    bg=max(cnt,key=lambda v:cnt[v]); fg=[v for v in cnt if v!=bg][0]
    rows=[r for r in range(H) if any(a[r][c]!=bg for c in range(W))]
    ub=rows[:len(rows)//2]; lb=rows[len(rows)//2:]
    best=None
    for s in range(-W,W+1):
        m=0
        for u in ub:
            for l in lb:
                for c in range(W):
                    t_=(a[u][c]==fg); b_=(a[l][(c-s)%W]==fg)
                    if t_!=b_: m+=1
        key=(m,s)
        if best is None or key<best: best=key
    s=best[1]
    out=[r[:] for r in a]
    for u,l in zip(ub,lb):
        for c in range(W):
            t_=a[u][c]==fg; bot=a[l][(c-s)%W]==fg
            if t_ and not bot: out[l][c]=1
    print(i,'match' if out==b else 'MISMATCH')
    if out!=b:
        dd=[(u,c,out[u][c],b[u][c]) for u in range(H) for c in range(W) if out[u][c]!=b[u][c]]
